// LLM-driven conversation compaction — replaces programmatic XML summary
// with structured 9-section summary generated by a lightweight model.
//
// Multi-provider via Anthropic SDK (both MiniMax and DeepSeek support it):
//   MiniMax-* → https://api.minimaxi.com/anthropic
//   deepseek-* → https://api.deepseek.com/anthropic
//
// Based on Claude Code's services/compact/prompt.ts + compact.ts patterns:
//   - 9-section structured output format (adapted for customer service)
//   - Chain-of-thought stripping: <analysis> discarded, <summary> kept
//   - Falls back to programmatic buildCompactionSummary on error

import Anthropic from '@anthropic-ai/sdk'
import type { Message, MemoryStrategy } from '@intera/shared/types'
import { withRetry, CannotRetryError } from './api/with-retry'

// 9-section prompt adapted from Claude Code's summarization prompt,
// tailored for customer service rather than code.
export const COMPACT_SYSTEM_PROMPT = `Your task is to create a detailed summary of the conversation so far, paying close attention to the customer's explicit requests and the agent's previous actions. This summary must be thorough in capturing case details, facts discovered, and decisions made — essential for continuing support work without losing context.

Before providing your final summary, wrap your analysis in <analysis> tags to organize your thoughts and ensure you've covered all necessary points. In your analysis process:

1. Chronologically analyze each message and section of the conversation. For each section thoroughly identify:
   - The customer's explicit requests and intents
   - The agent's approach to addressing those requests
   - Key decisions, facts discovered, and tools used
   - Specific details like: transaction IDs, amounts, dates, payment methods, case status
   - Errors encountered and how they were handled
   - Pay special attention to customer feedback, especially if the customer corrected something.

2. Double-check for factual accuracy and completeness, addressing each required element thoroughly.

Your summary should include the following sections:

1. Primary Customer Request and Intent: Capture the customer's explicit requests and intents in detail.
2. Key Facts Discovered: List all confirmed facts (transaction IDs, amounts, dates, statuses) discovered through tools or customer statements.
3. Skills/Tools Executed and Results: Enumerate tools called and their key outputs. Include query results, search findings, etc.
4. Errors and Conflicts: List any errors, data conflicts, or discrepancies encountered.
5. Problem Solving: Document problems resolved and any ongoing troubleshooting.
6. All Customer Messages: Summarize ALL customer messages (not tool results). These are critical for understanding changing intent.
7. Pending Information: List information still needed from the customer or from system queries.
8. Current Case State: Describe the current case status, stage, and any active escalations.
9. Optional Next Step: Suggest the next action, directly aligned with the customer's most recent request. Do not start tangential actions.

Here's an example of how your output should be structured:

<analysis>
[Your thought process, ensuring all points are covered thoroughly and accurately]
</analysis>
<summary>
1. Primary Customer Request and Intent: [Detailed description]
2. Key Facts Discovered:
   - [Fact 1]
   - [Fact 2]
3. Skills/Tools Executed and Results:
   - [Tool 1]: [Result]
4. Errors and Conflicts: [Description or "None"]
5. Problem Solving: [Description]
6. All Customer Messages: [Summary of each customer message]
7. Pending Information: [List of missing facts]
8. Current Case State: [Current status and stage]
9. Optional Next Step: [Suggested next action]
</summary>

CRITICAL: Respond with TEXT ONLY. Do NOT call any tools. Tool calls will be REJECTED and will waste your only turn — you will fail the task.

When summarizing, focus on customer service case details and remember any mistakes made and how they were fixed. Include facts and transaction data verbatim where possible.`

/**
 * Strip <analysis> tags from the summary output, keeping only <summary> content.
 */
export function formatCompactSummary(raw: string): string {
  let formatted = raw
  formatted = formatted.replace(/<analysis>[\s\S]*?<\/analysis>/gi, '')
  const summaryMatch = formatted.match(/<summary>([\s\S]*?)<\/summary>/i)
  if (summaryMatch) {
    formatted = `Summary:\n${summaryMatch[1]?.trim()}`
  }
  return formatted.trim()
}

export interface CompactConversationResult {
  summary: string | null
  model: string
  provider: string
  tokensUsed?: number
  error?: string
}

// Provider → API key + base URL mapping for Anthropic-compatible endpoints
function getProviderConfig(model: string): { apiKey: string | undefined; baseURL: string | undefined; provider: string } {
  if (model.startsWith('deepseek-')) {
    return {
      apiKey: process.env.DEEPSEEK_API_KEY,
      baseURL: process.env.DEEPSEEK_BASE_URL || 'https://api.deepseek.com/anthropic',
      provider: 'deepseek',
    }
  }
  if (model.startsWith('MiniMax-')) {
    return {
      apiKey: process.env.MINIMAX_API_KEY,
      baseURL: process.env.MINIMAX_BASE_URL || 'https://api.minimaxi.com/anthropic',
      provider: 'minimax',
    }
  }
  // Fallback: use default Anthropic config
  return {
    apiKey: process.env.ANTHROPIC_AUTH_TOKEN,
    baseURL: process.env.ANTHROPIC_BASE_URL,
    provider: 'anthropic',
  }
}

/**
 * Call a lightweight model to generate a structured conversation summary.
 * Both MiniMax and DeepSeek support Anthropic-compatible API endpoints, so
 * all providers use the Anthropic SDK with different baseURL/apiKey.
 *
 * Falls back to returning null on error — caller should use programmatic fallback.
 */
export async function compactConversation(
  messages: Message[],
  strategy: MemoryStrategy,
): Promise<CompactConversationResult> {
  const model = strategy.compactModel || 'MiniMax-M2.5-highspeed'
  const { apiKey, baseURL, provider } = getProviderConfig(model)

  if (!apiKey) {
    return { summary: null, model, provider, error: `API key not configured for ${provider}` }
  }

  const systemPrompt = strategy.compactPrompt || COMPACT_SYSTEM_PROMPT

  const apiMessages = messages
    .filter((m) => typeof m.content === 'string' && m.content.trim().length > 0)
    .map((m) => ({
      role: m.role === 'user' ? 'user' as const : 'assistant' as const,
      content: m.content as string,
    }))
    .slice(-(strategy.compactMaxMessages || 20))

  try {
    const client = new Anthropic({ apiKey, baseURL })

    const response = await withRetry(
      (retryClient, ctx) => retryClient.messages.create({
        model: ctx.model,
        max_tokens: Math.min(strategy.l2SummaryMaxTokens, strategy.compactMaxTokensCap),
        system: systemPrompt,
        messages: apiMessages,
        temperature: strategy.compactTemperature,
        thinking: { type: 'disabled' as const },
      }),
      { querySource: 'compact', model },
      () => new Anthropic({ apiKey, baseURL }),
    )

    const rawText = response.content
      .filter((block) => block.type === 'text')
      .map((block) => (block as { type: 'text'; text: string }).text)
      .join('')

    if (!rawText) {
      return { summary: null, model, provider, error: 'Empty response' }
    }

    const summary = formatCompactSummary(rawText)
    if (!summary || summary.length < strategy.compactMinSummaryLength) {
      return { summary: null, model, provider, error: 'Summary too short' }
    }

    return {
      summary,
      model,
      provider,
      tokensUsed: response.usage?.input_tokens
        ? response.usage.input_tokens + (response.usage.output_tokens || 0)
        : undefined,
    }
  } catch (err) {
    const errorMsg = err instanceof Error ? err.message : 'Unknown error'
    console.warn(`[Compact] ${provider} call failed (${model}):`, errorMsg)
    return { summary: null, model, provider, error: errorMsg }
  }
}

/**
 * Context collapse: persists a compressed snapshot of the conversation
 * to the CaseMemory.summary field, allowing the agent to restore context
 * across restarts without keeping all messages in memory.
 */
export async function contextCollapse(
  messages: Message[],
  memoryStrategy: import('@intera/shared/types').MemoryStrategy,
  caseId: string,
): Promise<string | null> {
  if (messages.length < 6) return null // not enough context to collapse
  const result = await compactConversation(messages, memoryStrategy)
  return result.summary
}

/**
 * Reactive compact: emergency trim when context overflows (413 error).
 * Keeps only the last N messages plus system prompt.
 */
export function reactiveCompact(messages: Message[], keepLast: number = 4): Message[] {
  if (messages.length <= keepLast) return messages
  const systemMsgs = messages.filter((m) => m.role === 'system')
  const recentMsgs = messages.slice(-keepLast)
  return [...systemMsgs, ...recentMsgs]
}
